-- 012: WTKU teisėjų žinių testas (Treneriams -> Teisėjų testas, nariams - teiseju-testas.php)
-- Klausimų bankas (300 klausimų iš WTKU Traditional Karate Competition Rules), bandymai ir kas gali laikyti.
-- Nustatymai (klausimų skaičius, išlaikymo riba, laikas...) saugomi site_settings (žr. 011), name = 'referee_test'.
SET NAMES utf8mb4;

-- Klausimai. topic - tas pats klausimas keliomis formuluotėmis: viename teste iš vienos temos būna tik vienas klausimas.
-- Atsakymų tvarka kiekvienam bandymui sumaišoma atsitiktinai.
CREATE TABLE referee_questions (
  id          INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  category    VARCHAR(60)  NOT NULL,
  topic       VARCHAR(190) NOT NULL,
  question    VARCHAR(500) NOT NULL,
  correct     VARCHAR(255) NOT NULL,
  wrong1      VARCHAR(255) NOT NULL,
  wrong2      VARCHAR(255) NULL,
  wrong3      VARCHAR(255) NULL,
  source      VARCHAR(120) NULL,                -- vieta taisyklėse, pvz. "II dalis, 1 str., p. 12"
  is_active   TINYINT(1) NOT NULL DEFAULT 1,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_rq_category (category, topic)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Kas gali laikyti, kai nustatymuose pasirinkta "tik pažymėti" (treneriai gali visada)
CREATE TABLE referee_access (
  account_id  INT UNSIGNED NOT NULL PRIMARY KEY,
  added_by    INT UNSIGNED NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ra_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE,
  CONSTRAINT fk_ra_by      FOREIGN KEY (added_by)   REFERENCES accounts(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bandymai. Klausimų skaičius, išlaikymo riba ir laikas įrašomi pradedant -
-- vėliau pakeitus nustatymus, jau pradėti testai ir seni rezultatai nesikeičia.
CREATE TABLE referee_attempts (
  id              INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  account_id      INT UNSIGNED NOT NULL,
  mode            ENUM('exam','practice') NOT NULL,
  category        VARCHAR(60) NULL,             -- mokomasis testas iš vieno skyriaus (NULL - iš visų)
  question_count  SMALLINT UNSIGNED NOT NULL,
  pass_percent    TINYINT UNSIGNED NOT NULL,
  started_at      DATETIME NOT NULL,
  deadline_at     DATETIME NULL,                -- NULL - be laiko limito
  finished_at     DATETIME NULL,
  score           SMALLINT UNSIGNED NULL,
  passed          TINYINT(1) NULL,
  KEY idx_rat_account (account_id, mode, started_at),
  KEY idx_rat_mode (mode, started_at),
  CONSTRAINT fk_rat_account FOREIGN KEY (account_id) REFERENCES accounts(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Bandymo klausimai. answer_order - rodomų atsakymų tvarka, pvz. "2031" (0 = correct, 1-3 = wrong1-3).
-- chosen - kurį iš rodomų atsakymų pasirinko (0 = pirmas rodomas); NULL - neatsakė.
CREATE TABLE referee_answers (
  attempt_id    INT UNSIGNED NOT NULL,
  position      SMALLINT UNSIGNED NOT NULL,
  question_id   INT UNSIGNED NOT NULL,
  answer_order  VARCHAR(4) NOT NULL,
  chosen        TINYINT UNSIGNED NULL,
  PRIMARY KEY (attempt_id, position),
  KEY idx_ran_question (question_id),
  CONSTRAINT fk_ran_attempt  FOREIGN KEY (attempt_id)  REFERENCES referee_attempts(id)  ON DELETE CASCADE,
  CONSTRAINT fk_ran_question FOREIGN KEY (question_id) REFERENCES referee_questions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Klausimų bankas: 100 temų po 3 formuluotes
